type LoginVM struct {
    mu   sync.RWMutex
    user string
    subs []func(string)
}
func (vm *LoginVM) SetUser(u string) {
    vm.mu.Lock()
    if vm.user == u { vm.mu.Unlock(); return }
    vm.user = u
    subs := slices.Clone(vm.subs); vm.mu.Unlock()   // never call out locked
    for _, fn := range subs { fn(u) }
}
